  "code": "// Copy order total to client: reads the order's client link and total, then\n// plans one update on the client card. The client collection must be in the\n// module's consent too, or the run fails.\nmorkva.action('copyTotal', async (input, ctx) => {\n  const order = ctx.card;\n  if (!order || !('values' in order)) return 'No order';\n  const links = order.values[input.clientField];\n  const client = Array.isArray(links) ? links[0] : undefined;\n  if (!client) return `${order.title} has no client`;\n  const total = order.values[input.totalField];\n  if (typeof total !== 'number') return `${order.title} has no total`;\n\n  // A link value holds card ids, not the collection: the schema names it.\n  const schema = await morkva.call('collections.get', {\n    collection: order.collectionId,\n    fields: [input.clientField],\n  });\n  const link = schema.fields.find((f) => f.id === input.clientField);\n  const clients = link && link.targetCollectionId;\n  if (typeof clients !== 'string') return `${input.clientField} is not a link`;\n\n  const name = client.title || 'the client';\n  try {\n    // Refused with \"Collection not available to this module\" when the\n    // consent leaves out the client collection.\n    await morkva.call('cards.update', {\n      collection: clients,\n      target: { ids: [client.id] },\n      set: { [input.targetField]: total },\n    });\n  } catch (e) {\n    // The client already holds this total: nothing to do, not a failure.\n    if (/** @type {MorkvaError} */ (e).code === 'no_change') {\n      return `${name} is up to date`;\n    }\n    throw e;\n  }\n  return `Copied ${total} to ${name}`;\n});\n"
}''',
  'low-stock-flag': r'''
{
  "morkva": 1,
  "manifest": {
    "id": "low-stock-flag",
    "name": "Flag low stock",
    "version": "1.0.0",
    "description": "Ticks a checkbox on every product whose stock is below a threshold. Bind it to a collection button.",
    "author": "SDK example",
    "apiVersion": 2,
    "permissions": {
      "capabilities": [
        "schema:read",
        "data:read",
        "data:write"
      ]
    },
    "actions": [
      {
        "id": "flagLow",
        "label": "Flag low stock",
        "scope": "collection",
        "icon": "flag",
        "input": {
          "type": "object",
          "required": [
            "stockField",
            "flagField",
            "below"
          ],
          "properties": {
            "stockField": {
              "type": "string",
              "title": "Stock field",
              "format": "field"
            },
            "flagField": {
              "type": "string",
              "title": "Checkbox to tick",
              "format": "field"
            },
            "below": {
              "type": "number",
              "title": "Below",
              "description": "Flag products with less than this in stock.",
              "minimum": 0,
              "default": 20
            }
          }
        }
      }
    ]
  },
  "code": "// Flag low stock: one query for the low-stock cards that are not flagged\n// yet, then one update that ticks the checkbox on all of them.\nmorkva.action('flagLow', async (input, ctx) => {\n  // A test run wraps the button trigger as {kind: 'test', as}. It passes\n  // no card ids, so it checks the whole collection.\n  const test = ctx.trigger.kind === 'test';\n  const trigger = ctx.trigger.kind === 'test' ? ctx.trigger.as : ctx.trigger;\n  if (trigger.kind !== 'button' || trigger.scope !== 'collection') {\n    return 'Run it from a collection button';\n  }\n  // A button run handles only the cards shown in the view it was pressed on.\n  const shown = new Set(trigger.cardIds);\n  if (!test && shown.size === 0) return 'No products shown';\n  const collection = trigger.collectionId;\n\n  const low = [];\n  /** @type {CardsQueryResult | CardsPageResult} */\n  let page = await morkva.call('cards.query', {\n    collection,\n    where: [\n      { field: input.stockField, op: 'lessThan', value: input.below },\n      { field: input.flagField, op: 'isFalse' },\n    ],\n    limit: 100,\n  });\n  for (;;) {\n    for (const row of page.rows) {\n      if (test || shown.has(row.id)) low.push(row.id);\n    }\n    morkva.progress({ done: low.length, total: page.total, label: 'Checking stock' });\n    if (!page.nextCursor) break;\n    page = await morkva.call('cards.page', {\n      handle: page.handle,\n      cursor: page.nextCursor,\n    });\n  }\n  if (low.length === 0) return 'No products to flag';\n\n  await morkva.call('cards.update', {\n    collection,\n    target: { ids: low },\n    set: { [input.flagField]: true },\n  });\n  return `Flagged ${low.length} product${low.length === 1 ? '' : 's'}`;\n});\n"
}''',
